def is_match(s: str, p: str) -> bool:
    # Initialize a 2D DP table where dp[i][j] will be True if s[:i] matches p[:j]
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]

    # Base case: empty pattern matches empty string
    dp[0][0] = True

    # Handle patterns like a*, a*b* etc.
    for j in range(2, len(p) + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    # Fill the DP table
    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2]  # Zero occurrence of the preceding element
                if p[j - 2] == '.' or p[j - 2] == s[i - 1]:
                    dp[i][j] |= dp[i - 1][j]  # One or more occurrences of the preceding element

    return dp[len(s)][len(p)]

# Example usage:
print(is_match("aa", "a"))  # Output: False
print(is_match("aa", "a*"))  # Output: True
print(is_match("ab", ".*"))  # Output: True
